SELECT jsonb_build_object('owner_guards_reenabled',(SELECT count(*)=5 AND bool_and(t.tgenabled='O') FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='app' AND c.relname IN ('users','user_security_profiles','track_plans','track_entitlement_definitions','track_plan_entitlements') AND t.tgname='owner_commit'),'no_project_user_trigger_disabled',NOT EXISTS(SELECT 1 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('app','platform','platform_private') AND NOT t.tgisinternal AND t.tgenabled<>'O'));
